app.post('/api/products/:id/purchase',auth,requireVerified,async(req,res,next)=>{try{const p=(await q('SELECT * FROM products WHERE id=$1 AND active=true',[req.params.id])).rows[0];if(!p)return res.status(404).json({error:'Product not found or no longer available'});if(String(p.seller_id)===String(req.user.id))return res.status(400).json({error:'You cannot purchase your own listing'});if(Number(p.price)<=0)return res.status(400).json({error:'Invalid price'});const reference=`PRODILIVE_PRODUCT_${p.id}_${Date.now()}`;const pay=await paystack('/transaction/initialize','POST',{email:req.user.email,amount:Math.round(Number(p.price)*100),currency:'NGN',reference,metadata:{productId:p.id,type:'MARKETPLACE_PRODUCT'}});await q('INSERT INTO product_orders(product_id,buyer_id,seller_id,amount,reference,status) VALUES($1,$2,$3,$4,$5,$6)',[p.id,req.user.id,p.seller_id,p.price,reference,'INITIALIZED']);await audit('PRODUCT_PURCHASE_INITIALIZED',req.user.id,{productId:p.id,reference});res.json({authorization_url:pay.authorization_url,access_code:pay.access_code,reference})}catch(e){next(e)}});

app.get('/api/product-orders/verify/:reference',auth,async(req,res,next)=>{try{const o=(await q('SELECT * FROM product_orders WHERE reference=$1 AND buyer_id=$2',[req.params.reference,req.user.id])).rows[0];if(!o)return res.sendStatus(404);if(o.status==='PAID')return res.json({status:'success',reference:o.reference});const remote=await paystack('/transaction/verify/'+encodeURIComponent(o.reference));if(remote.status==='success'){const expectedKobo=Math.round(Number(o.amount)*100);if(Number(remote.amount)!==expectedKobo||String(remote.currency||'NGN')!=='NGN')return res.status(400).json({error:'Payment amount or currency mismatch'});await q("UPDATE product_orders SET status='PAID',paid_at=now(),provider_payload=$1 WHERE id=$2",[remote,o.id]);await q('UPDATE products SET sales_count=sales_count+1 WHERE id=$1',[o.product_id]);await notify(o.seller_id,'PRODUCT_SALE','You made a sale!',`Your listing sold for ₦${o.amount}.`,{productId:o.product_id});await audit('PRODUCT_PURCHASE_VERIFIED','PAYSTACK',{productId:o.product_id,reference:o.reference})}res.json({status:remote.status,reference:o.reference})}catch(e){next(e)}});

