app.post('/api/jobs/:id/review',auth,roles('client'),async(req,res,next)=>{try{const rating=Number(req.body.rating),comment=String(req.body.comment||'').trim().slice(0,3000);if(!Number.isInteger(rating)||rating<1||rating>5)return res.status(400).json({error:'Rating must be an integer from 1 to 5'});const j=(await q('SELECT * FROM jobs WHERE id=$1 AND client_id=$2',[req.params.id,req.user.id])).rows[0];if(!j||j.status!=='RELEASED')return res.status(400).json({error:'Job must be released before review'});if((await q('SELECT 1 FROM reviews WHERE job_id=$1 AND reviewer_id=$2',[j.id,req.user.id])).rowCount)return res.status(409).json({error:'Review already submitted'});const r=await q('INSERT INTO reviews(job_id,reviewer_id,reviewee_id,rating,comment) VALUES($1,$2,$3,$4,$5) RETURNING *',[j.id,req.user.id,j.talent_id,rating,comment]);await audit('REVIEW_SUBMITTED',req.user.id,{jobId:j.id,reviewId:r.rows[0].id,rating});res.status(201).json(r.rows[0])}catch(e){next(e)}});
