app.put('/api/admin/settings',auth,roles('admin'),async(req,res,next)=>{try{const allowed={commission:Number(req.body.commission),reviewWindowHours:Number(req.body.reviewWindowHours),autoApproveHours:Number(req.body.autoApproveHours)};if(!Number.isFinite(allowed.commission)||allowed.commission<0||allowed.commission>100||allowed.reviewWindowHours<1||allowed.autoApproveHours<1)return res.status(400).json({error:'Invalid settings'});for(const [k,v] of Object.entries(allowed))await q('INSERT INTO settings(key,value) VALUES($1,$2) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value',[k,JSON.stringify(v)]);await audit('ADMIN_UPDATED_SETTINGS',req.user.id,allowed);res.json({settings:allowed})}catch(e){next(e)}});
