app.post('/api/admin/reviewer-applications/:id/decision',auth,roles('admin'),async(req,res,next)=>{try{const approved=Boolean(req.body.approved),r=await q("UPDATE reviewer_applications SET status=$1,reviewed_by=$2,reviewed_at=now() WHERE id=$3 RETURNING *",[approved?'QUALIFICATION':'REJECTED',req.user.id,req.params.id]);if(!r.rowCount)return res.sendStatus(404);if(approved)await q("INSERT INTO reviewer_tests(application_id,user_id,status) VALUES($1,$2,'PENDING') ON CONFLICT(application_id) DO NOTHING",[r.rows[0].id,r.rows[0].user_id]);res.json(r.rows[0])}catch(e){next(e)}});
